CREATE TABLE IF NOT EXISTS employee_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_id uuid REFERENCES employees(id) NOT NULL, review_period text NOT NULL, rating text, objectives text, strengths text, development_needs text, reviewer text, status text NOT NULL DEFAULT 'Draft', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS succession_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), position_id uuid REFERENCES org_positions(id) NOT NULL, readiness_level text NOT NULL DEFAULT 'No Successor', primary_successor text, secondary_successor text, criticality text NOT NULL DEFAULT 'Standard', development_actions text, review_date date, status text NOT NULL DEFAULT 'Active', created_at timestamptz NOT NULL DEFAULT now());